    interface PilotAction {void run() throws Exception;}
    void runPilotTask(PilotAction action,String success){new Thread(()->{String result;try{action.run();result=success;}catch(Exception e){result="Could not sync: "+e.getMessage()+". Your data stays local; retry when the server is available.";}String message=result;runOnUiThread(()->{if(!isDestroyed())new AlertDialog.Builder(this).setMessage(message).setPositiveButton("OK",null).show();});},"pilot-action").start();}
    void reportMessage(JSONObject row){
        if(!Store.prefs(this).getBoolean("pilot_consent",false)){Toast.makeText(this,"Join the development pilot first",Toast.LENGTH_LONG).show();return;}
        LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);EditText body=new EditText(this);body.setHint("Paste a missed message locally; only masked grammar will be sent");if(row==null)box.addView(body);
        String[] issues={"wrong_amount","wrong_direction","wrong_name","wrong_category","not_transaction","missing_transaction","duplicate","missed_recurring","other"};Spinner issue=new Spinner(this);issue.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,issues));box.addView(issue);
        String[] expected={"unknown","debit","credit","receipt","event","ignore"};Spinner expect=new Spinner(this);expect.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,expected));box.addView(expect);
        new AlertDialog.Builder(this).setTitle("Report a message format").setView(box).setPositiveButton("Preview",(d,w)->{String raw=body.getText().toString();String shape=row==null?MessagePatterns.shape(raw):row.optString("shape");if(shape.isEmpty()||row==null&&MessagePatterns.family(raw).equals("OTP / verification")){Toast.makeText(this,"No shareable pattern; OTPs are excluded. Re-import old entries to populate grammar.",Toast.LENGTH_LONG).show();return;}String issuer=row==null?Issuer.inText(raw):row.optString("issuer");body.setText("");String choice=issue.getSelectedItem().toString(),want=expect.getSelectedItem().toString();new AlertDialog.Builder(this).setTitle("Only this grammar is shared").setMessage(shape+"\nIssue: "+choice+"\nExpected: "+want+"\nNo amounts, names, references or original text.").setPositiveButton("Submit",(x,y)->{Learning.report(this,shape,issuer,choice,want);runPilotTask(()->PilotSync.sync(this),"Report sent. Check progress in Development pilot.");}).setNegativeButton("Cancel",null).show();}).setNegativeButton("Cancel",null).show();
    }
    void eventStatus(){JSONArray a=FinancialEvents.rows(this);java.util.List<JSONObject> list=new java.util.ArrayList<>();for(int i=a.length()-1;i>=0&&list.size()<80;i--)list.add(a.optJSONObject(i));String[] labels=list.stream().map(e->e.optString("type")+" · "+e.optString("dueDate")+" · "+e.optString("issuer")+" · "+Store.money(e.optLong("amount"))).toArray(String[]::new);new AlertDialog.Builder(this).setTitle("Select evidence").setItems(labels,(d,w)->{JSONObject e=list.get(w);String[] states={"Open","Paid / received","Cancelled","Dismissed"};new AlertDialog.Builder(this).setTitle("You confirm the status").setItems(states,(x,y)->{FinancialEvents.resolve(this,e.optString("id",e.optString("fingerprint")),states[y]);render();}).show();}).show();}
    void commitments(){
        java.util.List<RecurringEngine.Payment> payments=new java.util.ArrayList<>();JSONArray all=LedgerDb.get(this).recent(System.currentTimeMillis()-800L*86400000L,false);for(int i=0;i<all.length();i++){JSONObject r=all.optJSONObject(i);if(!r.optString("direction").equals("debit")||r.optString("source").equals("sample"))continue;String identity=r.optString("source")+"|"+r.optString("issuer")+"|"+r.optString("account")+"|"+r.optString("merchant").trim().toLowerCase(java.util.Locale.ROOT);payments.add(new RecurringEngine.Payment(r.optString("id"),identity,r.optString("merchant"),r.optString("category"),r.optLong("paise"),java.time.Instant.ofEpochMilli(r.optLong("time")).atZone(java.time.ZoneId.systemDefault()).toLocalDate(),r.optBoolean("reviewed")));}
        java.util.List<RecurringEngine.Series> series=RecurringEngine.analyze(payments,java.time.LocalDate.now());LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(20),dp(10),dp(20),dp(10));box.addView(text("Candidates from payment intervals. Announced bills are separate in Financial events. Amount ranges are past charges; mandate ceilings are not forecasts. Same merchant can represent multiple services.",14,muted,false));
        for(RecurringEngine.Series r:series){String key="series_"+Store.fingerprint(r.identity(),0);String state=Store.prefs(this).getString(key,"Needs confirmation");box.addView(text(r.merchant()+" · "+r.kind()+" · "+state,17,green,true));box.addView(text(r.cadence()+" · estimated next "+r.next()+"\n"+(r.variable()?"Past range "+Store.money(r.low())+"–"+Store.money(r.high()):"Last paid "+Store.money(r.latest()))+"\n"+r.evidence(),14,ink,false));Button status=new Button(this);status.setText("Confirm / pause / dismiss");status.setOnClickListener(v->new AlertDialog.Builder(this).setTitle(r.merchant()).setItems(new String[]{"Confirmed recurring","Paused","Cancelled","Not recurring"},(d,w)->{Store.prefs(this).edit().putString(key,new String[]{"Confirmed recurring","Paused","Cancelled","Not recurring"}[w]).apply();Toast.makeText(this,"Saved. This does not cancel a provider mandate.",Toast.LENGTH_LONG).show();}).show());box.addView(status);}
        if(series.isEmpty())box.addView(text("No supported recurring series yet. Two observations can suggest a candidate; review the payments and confirm with your provider. Missing messages can hide a series.",14,muted,false));ScrollView scroll=new ScrollView(this);scroll.addView(box);new AlertDialog.Builder(this).setTitle("Recurring payments").setView(scroll).setPositiveButton("Done",null).show();
    }

    void paymentChecks(){
        StringBuilder text=new StringBuilder("Checks are prompts for your review, not proof of fraud. No entries are removed automatically.\n\n");JSONArray events=FinancialEvents.rows(this);int requests=0,failures=0;long since=System.currentTimeMillis()-86400000L;
        for(int i=0;i<events.length();i++){JSONObject e=events.optJSONObject(i);if(e.optLong("time")<since||!e.optString("status","Open").equals("Open"))continue;if(e.optString("type").equals("Payment request"))requests++;if(e.optString("type").equals("Failed payment"))failures++;}
        text.append(requests).append(" payment requests in the last day. A request is not an authorised debit; check the requesting app.\n").append(failures).append(" failed-payment notices in the last day. Repeated notices may describe the same attempt.\n\n");
        java.util.List<PaymentChecks.Movement> input=new java.util.ArrayList<>();JSONArray a=LedgerDb.get(this).recent(since,false);for(int i=0;i<a.length();i++){JSONObject r=a.optJSONObject(i);if(!r.optString("direction").equals("debit")||java.util.List.of("Transfer","Payment receipt","Not a transaction").contains(r.optString("category"))||r.optString("source").equals("sample"))continue;input.add(new PaymentChecks.Movement(r.optString("id"),r.optString("issuer"),r.optString("account"),r.optString("merchant"),r.optString("reference"),r.optLong("paise"),r.optLong("time")));}
        var flags=PaymentChecks.possibleDoublePayments(input);for(var f:flags)text.append(f.explanation()).append("\nEntries: ").append(f.firstId().substring(0,8)).append(" / ").append(f.secondId().substring(0,8)).append("\n\n");if(flags.isEmpty())text.append("No supported possible double-payment pair found. This does not prove that all charges are correct.");
        new AlertDialog.Builder(this).setTitle("Payment checks").setMessage(text.toString()).setPositiveButton("Done",null).show();
    }

